exports.makeBody = function makeBody() {
  return { label: "ok", count: 3, nested: { flag: true }, tags: ["a", "b"] };
};

exports.makeList = function makeList() {
  return [1, 2, 3];
};

exports.makeHooks = function makeHooks() {
  return {
    label: "hooks",
    toJSON() {
      return { kind: "custom" };
    },
  };
};

exports.makeWithMembers = function makeWithMembers() {
  return {
    name: "members",
    run() {
      return 1;
    },
    get size() {
      return 7;
    },
    missing: undefined,
  };
};

// A declared field the object inherits from its prototype: an ordinary
// property read answers it, an own-key snapshot does not.
exports.makeInherited = function makeInherited() {
  const base = { label: "inherited" };
  const made = Object.create(base);
  made.count = 3;
  return made;
};

// A declared field the object defines as non-enumerable: it is its own
// property, but no own-key enumeration reports it.
exports.makeHidden = function makeHidden() {
  const made = { visible: 1 };
  Object.defineProperty(made, "hidden", { value: 2, enumerable: false });
  return made;
};

// A value that refers to itself: a record conversion has to recognize the
// same object when a member read answers it again.
exports.makeCycle = function makeCycle() {
  const made = { name: "cycle" };
  made.next = made;
  return made;
};

// A declared field of an index-signature record that is a getter: the
// conversion reads it once, as the record's field, and the caller sees the
// first answer.
exports.makeCounting = function makeCounting() {
  let calls = 0;
  return {
    plain: 1,
    get counted() {
      calls += 1;
      return calls;
    },
  };
};

// A symbol and an array holding one: a symbol has no JSON text.
exports.makeSymbols = function makeSymbols() {
  return { tag: Symbol("tag"), list: [Symbol("item")] };
};

// An array behind a proxy: Array.isArray follows the proxy to its target.
exports.makeProxyList = function makeProxyList() {
  return new Proxy([4, 5], {});
};

// Four discriminated records: a checked conversion reads the discriminant
// through the handle before it can pick the arm.
exports.makeShapes = function makeShapes() {
  return [
    { kind: "circle", radius: 3 },
    { kind: "square", side: 4 },
    { kind: "triangle", base: 2, height: 5 },
    { kind: "line", length: 9 },
  ];
};
